private final Semaphore dbSlots = new Semaphore(8);

if (!dbSlots.tryAcquire(50, TimeUnit.MILLISECONDS))
    return Response.status(503).build();      // saturated

try {
    return db.query(sql);
} finally {
    dbSlots.release();                        // every exit path
}

